/* ---------------------------------------------------------------------------
   QueryBuilder.js (Calcite port)
   Click-to-append WHERE-clause builder, ported from webroot5/5/js/QueryBuilder.js.

   Shape preserved:
     - Step 1: layer picker (Calcite dropdown of queryable layers)
     - Field picker (calcite-select populated from the layer's REST schema)
     - Operator pad (calcite-buttons for =, <>, LIKE, AND, OR, (, ), ...)
     - Distinct-value picker (calcite-select, populated on field change)
     - WHERE textarea (calcite-text-area)
     - Run / Clear (calcite-buttons)
     - Status line (aria-live, so screen readers pick up "N fields loaded" etc.)

   onSubmit(layerConfig, whereClause) stays the same, so app.js keeps its
   single submit pipeline.
   --------------------------------------------------------------------------- */

import { fetchLayerFields, queryForDistinctValues } from "./QueryEngine.js";

const OPERATORS = [
  "=", "<>", "<", ">", "<=", ">=",
  "LIKE", "IN", "IS", "NOT", "NULL",
  "%", "_",
  "AND", "OR", "(", ")",
];

const STRING_TYPES = new Set([
  "esriFieldTypeString", "esriFieldTypeGUID", "esriFieldTypeGlobalID",
  "esriFieldTypeDate", "string",
]);

export class QueryBuilder {
  /**
   * @param {Object} options
   * @param {HTMLElement} options.container
   * @param {Array<{id,title,queryUrl,oidField?,actionType?,priorityFields?,deprioritizedFields?}>} options.layers
   * @param {Function} options.onSubmit  (layerConfig, where) => void
   */
  constructor({ container, layers, onSubmit }) {
    this.container = container;
    this.layers = layers;
    this.onSubmit = onSubmit || (() => {});

    this._fields = [];
    this._selectedField = null;
    this._layerId = layers[0]?.id ?? null;
    this._build();
    this._onLayerChange();
  }

  get selectedLayer() {
    return this.layers.find((l) => l.id === this._layerId);
  }

  setStatus(msg) { this._statusEl.textContent = msg || ""; }

  // ── build ───────────────────────────────────────────────────────────────

  _build() {
    this.container.replaceChildren();
    this.container.classList.add("qb-panel");

    // Step 1: Layer
    const layerRow = document.createElement("div");
    layerRow.className = "qb-row qb-row-layer";

    const layerLabel = document.createElement("label");
    layerLabel.className = "qb-label";
    layerLabel.setAttribute("for", "qb-layer-select");
    layerLabel.textContent = "Layer";
    layerRow.appendChild(layerLabel);

    this._layerEl = document.createElement("calcite-select");
    this._layerEl.id = "qb-layer-select";
    this._layerEl.setAttribute("label", "Layer to query");
    this._layerEl.setAttribute("scale", "m");
    for (const l of this.layers) {
      const opt = document.createElement("calcite-option");
      opt.value = l.id;
      opt.textContent = l.title;
      if (l.id === this._layerId) opt.setAttribute("selected", "");
      this._layerEl.appendChild(opt);
    }
    this._layerEl.addEventListener("calciteSelectChange", () => {
      this._layerId = this._layerEl.value;
      this._onLayerChange();
    });
    layerRow.appendChild(this._layerEl);
    this.container.appendChild(layerRow);

    // Field + Add
    const fieldRow = document.createElement("div");
    fieldRow.className = "qb-row";
    const fieldLabel = document.createElement("label");
    fieldLabel.className = "qb-label";
    fieldLabel.setAttribute("for", "qb-field-select");
    fieldLabel.textContent = "Field";
    this._fieldEl = document.createElement("calcite-select");
    this._fieldEl.id = "qb-field-select";
    this._fieldEl.setAttribute("label", "Field");
    this._fieldEl.setAttribute("scale", "m");
    this._fieldEl.addEventListener("calciteSelectChange", () => {
      this._selectedField = this._fields.find((f) => f.name === this._fieldEl.value);
      this._loadDistinctValues();
    });
    const addFieldBtn = this._btn("Add", () => {
      if (this._fieldEl.value) this._append(this._fieldEl.value);
    });
    fieldRow.append(fieldLabel, this._fieldEl, addFieldBtn);
    this.container.appendChild(fieldRow);

    // Operator pad
    const opRow = document.createElement("div");
    opRow.className = "qb-row qb-row-ops";
    const opLabel = document.createElement("span");
    opLabel.className = "qb-label";
    opLabel.textContent = "Operators";
    opRow.appendChild(opLabel);
    const opPad = document.createElement("div");
    opPad.className = "qb-ops";
    opPad.setAttribute("role", "group");
    opPad.setAttribute("aria-label", "SQL operators");
    for (const op of OPERATORS) {
      const b = document.createElement("calcite-button");
      b.className = "qb-op-btn";
      b.setAttribute("appearance", "outline");
      b.setAttribute("kind", "neutral");
      b.setAttribute("scale", "s");
      b.textContent = op;
      b.addEventListener("click", () => this._append(op));
      opPad.appendChild(b);
    }
    opRow.appendChild(opPad);
    this.container.appendChild(opRow);

    // Value + Add
    const valRow = document.createElement("div");
    valRow.className = "qb-row";
    const valLabel = document.createElement("label");
    valLabel.className = "qb-label";
    valLabel.setAttribute("for", "qb-value-select");
    valLabel.textContent = "Value";
    this._valueEl = document.createElement("calcite-select");
    this._valueEl.id = "qb-value-select";
    this._valueEl.setAttribute("label", "Distinct value");
    this._valueEl.setAttribute("scale", "m");
    const addValBtn = this._btn("Add", () => {
      const v = this._valueEl.value;
      if (v === "" || v == null) return;
      this._append(this._formatValue(v));
    });
    valRow.append(valLabel, this._valueEl, addValBtn);
    this.container.appendChild(valRow);

    // WHERE textarea
    const whereRow = document.createElement("div");
    whereRow.className = "qb-row qb-row-where";
    const whereLabel = document.createElement("label");
    whereLabel.className = "qb-label";
    whereLabel.setAttribute("for", "qb-where");
    whereLabel.textContent = "WHERE";
    this._whereEl = document.createElement("calcite-text-area");
    this._whereEl.id = "qb-where";
    this._whereEl.setAttribute("label", "WHERE clause");
    this._whereEl.setAttribute("rows", "4");
    this._whereEl.setAttribute("placeholder", "WHERE clause…");
    whereRow.append(whereLabel, this._whereEl);
    this.container.appendChild(whereRow);

    // Run / Clear
    const footer = document.createElement("div");
    footer.className = "qb-footer";
    const runBtn = this._btn("Run", () => this._submit(), { kind: "brand", appearance: "solid" });
    const clearBtn = this._btn("Clear", () => { this._whereEl.value = ""; });
    footer.append(runBtn, clearBtn);
    this.container.appendChild(footer);

    // Status
    this._statusEl = document.createElement("div");
    this._statusEl.className = "qb-status";
    this._statusEl.setAttribute("aria-live", "polite");
    this._statusEl.setAttribute("aria-atomic", "true");
    this.container.appendChild(this._statusEl);
  }

  // ── behavior ────────────────────────────────────────────────────────────

  async _onLayerChange() {
    const layer = this.selectedLayer;
    if (!layer) return;
    this._whereEl.value = "";
    this._valueEl.replaceChildren();
    this._fieldEl.replaceChildren();
    this.setStatus("Loading fields…");
    try {
      const fields = await fetchLayerFields(layer.queryUrl);
      this._fields = fields;
      for (const f of fields) {
        const opt = document.createElement("calcite-option");
        opt.value = f.name;
        opt.textContent = `${f.alias} (${shortType(f.type)})`;
        this._fieldEl.appendChild(opt);
      }
      this._selectedField = fields[0] || null;
      this.setStatus(`${fields.length} fields loaded.`);
      if (this._selectedField) this._loadDistinctValues();
    } catch (err) {
      console.error(err);
      this.setStatus(`Failed to load fields: ${err.message || err}`);
    }
  }

  async _loadDistinctValues() {
    const layer = this.selectedLayer;
    const field = this._selectedField;
    if (!layer || !field) return;
    this.setStatus(`Fetching distinct values for ${field.name}…`);
    this._valueEl.replaceChildren();
    try {
      const values = await queryForDistinctValues(layer.queryUrl, field.name);
      for (const v of values) {
        const opt = document.createElement("calcite-option");
        opt.value = String(v);
        opt.textContent = String(v);
        this._valueEl.appendChild(opt);
      }
      this.setStatus(`${values.length} distinct values.`);
    } catch (err) {
      console.error(err);
      this.setStatus(`Distinct values failed: ${err.message || err}`);
    }
  }

  _submit() {
    const layer = this.selectedLayer;
    const where = (this._whereEl.value || "").trim();
    if (!layer)  { this.setStatus("Pick a layer."); return; }
    if (!where)  { this.setStatus("Build a WHERE clause first."); return; }
    this.setStatus("Running query…");
    this.onSubmit(layer, where);
  }

  _append(text) {
    const cur = this._whereEl.value || "";
    const sep = cur.length && !cur.endsWith(" ") ? " " : "";
    this._whereEl.value = cur + sep + text + " ";
    this._whereEl.setFocus?.();
  }

  _formatValue(v) {
    const f = this._selectedField;
    const isString = f && STRING_TYPES.has(f.type);
    if (!isString) return String(v);
    return `'${String(v).replace(/'/g, "''")}'`;
  }

  _btn(label, onClick, { kind = "neutral", appearance = "outline" } = {}) {
    const b = document.createElement("calcite-button");
    b.className = "qb-btn";
    b.setAttribute("kind", kind);
    b.setAttribute("appearance", appearance);
    b.setAttribute("scale", "m");
    b.textContent = label;
    b.addEventListener("click", onClick);
    return b;
  }
}

function shortType(t) {
  return (t || "").replace(/^esriFieldType/, "").toLowerCase();
}
