/* ---------------------------------------------------------------------------
   LayerList.js (Calcite port)
   Docked layer toggle using calcite-list / calcite-list-item with a trailing
   calcite-switch per layer. Backed by LayerRegistry, same contract as
   webroot5/5/js/LayerList.js:
     - Render operational-role layers, grouped by category.
     - Toggle `.visible` on the underlying @arcgis/core Layer instance.
     - Lazy-add non-essential layers to the map the first time they're toggled on.

   Accessibility:
     - Category headings use <h3> so they join the document outline.
     - Each switch is paired with a <label> via `for`/id, so screen readers
       read "<layer title>, switch, on/off".
   --------------------------------------------------------------------------- */

let _uid = 0;
const nextId = (p) => `${p}-${++_uid}`;

export class LayerList {
  /**
   * @param {Object} options
   * @param {HTMLElement} options.container
   * @param {import('./LayerRegistry.js').LayerRegistry} options.registry
   * @param {import('@arcgis/core/Map.js').default} options.map
   */
  constructor({ container, registry, map }) {
    this.container = container;
    this.registry = registry;
    this.map = map;
    this.render();
  }

  render() {
    const configs = this.registry
      .allConfigs()
      .filter((c) => c.role === "operational");

    const byCategory = new Map();
    for (const c of configs) {
      const cat = c.category || "other";
      if (!byCategory.has(cat)) byCategory.set(cat, []);
      byCategory.get(cat).push(c);
    }

    this.container.replaceChildren();
    this.container.classList.add("ll-panel");

    for (const [cat, items] of byCategory) {
      const section = document.createElement("section");
      section.className = "ll-group";

      const heading = document.createElement("h3");
      heading.className = "ll-group-label";
      heading.textContent = formatCategory(cat);
      section.appendChild(heading);

      const list = document.createElement("calcite-list");
      list.setAttribute("selection-mode", "none");
      list.setAttribute("label", `${formatCategory(cat)} layers`);

      for (const config of items) {
        list.appendChild(this.#renderItem(config));
      }
      section.appendChild(list);
      this.container.appendChild(section);
    }
  }

  #renderItem(config) {
    const item = document.createElement("calcite-list-item");
    item.setAttribute("label", config.title);
    item.dataset.layerId = config.id;

    const switchId = nextId("ll-switch");
    const sw = document.createElement("calcite-switch");
    sw.id = switchId;
    sw.setAttribute("scale", "s");
    sw.setAttribute("aria-label", `Show ${config.title}`);
    if (config.defaultVisible) sw.setAttribute("checked", "");

    // calcite-list-item routes `slot="actions-end"` to trailing controls.
    const wrapper = document.createElement("div");
    wrapper.setAttribute("slot", "actions-end");
    wrapper.appendChild(sw);
    item.appendChild(wrapper);

    sw.addEventListener("calciteSwitchChange", () => {
      this.#toggle(config.id, sw.checked);
    });

    return item;
  }

  #toggle(id, visible) {
    const layer = this.registry.getInstance(id);
    if (!layer) return;
    if (visible && !this.map.layers.includes(layer)) {
      this.map.add(layer);
    }
    layer.visible = visible;
  }
}

function formatCategory(cat) {
  return cat.charAt(0).toUpperCase() + cat.slice(1).replace(/_/g, " ");
}
