/* ---------------------------------------------------------------------------
   FieldPicker.js (Calcite port)
   Wires the existing <calcite-dropdown> / <calcite-input> in index.html to a
   field-keyed search spec, mirroring the `initFieldPicker` contract from
   webroot5/5/js/FieldPicker.js.

   Public surface:
     initFieldPicker({
       fields,          // [{ value, label, badge, chipKind, placeholder, spec }]
       dropdownId,      // id of the <calcite-dropdown>
       groupSelector,   // CSS selector for the <calcite-dropdown-group>
       triggerBtnId,    // id of the slot=trigger button
       triggerChipId,   // id of the leading chip
       triggerLabelId,  // id of the trigger label span
       inputId,         // id of the <calcite-input>
       onChange,        // fired as onChange(value, entry)
     })

   Returns { getField(), getSpec() }.
   --------------------------------------------------------------------------- */

export function initFieldPicker({
  fields,
  dropdownId = "field-dropdown",
  groupSelector = "calcite-dropdown-group",
  triggerBtnId = "field-trigger-btn",
  triggerChipId = "field-trigger-chip",
  triggerLabelId = "field-trigger-label",
  inputId = "search-input",
  onChange,
} = {}) {
  const dropdown = document.getElementById(dropdownId);
  const group    = dropdown?.querySelector(groupSelector);
  const trigger  = document.getElementById(triggerBtnId);
  const chip     = document.getElementById(triggerChipId);
  const labelEl  = document.getElementById(triggerLabelId);
  const input    = document.getElementById(inputId);
  if (!dropdown || !group || !trigger || !chip || !labelEl || !input) {
    throw new Error("FieldPicker: required Calcite elements missing from DOM");
  }

  const byValue = new Map();

  // Rebuild the dropdown items from the field list so the registry drives the UI.
  group.replaceChildren();
  for (let i = 0; i < fields.length; i++) {
    const f = fields[i];
    byValue.set(f.value, f);

    const item = document.createElement("calcite-dropdown-item");
    item.dataset.value       = f.value;
    item.dataset.label       = f.label;
    item.dataset.badge       = f.badge ?? f.label.charAt(0).toUpperCase();
    item.dataset.chipKind    = f.chipKind ?? "brand";
    item.dataset.placeholder = f.placeholder ?? `Search by ${f.label.toLowerCase()}`;
    if (i === 0) item.setAttribute("selected", "");

    const itemChip = document.createElement("calcite-chip");
    itemChip.setAttribute("appearance", "solid");
    itemChip.setAttribute("kind", f.chipKind ?? "brand");
    itemChip.setAttribute("scale", "s");
    itemChip.textContent = f.badge ?? f.label.charAt(0).toUpperCase();
    item.appendChild(itemChip);
    item.append(` ${f.label}`);

    group.appendChild(item);
  }

  let current = fields[0];
  applyToTrigger(current);

  dropdown.addEventListener("calciteDropdownSelect", () => {
    const selected = dropdown.selectedItems?.[0];
    if (!selected) return;
    const entry = byValue.get(selected.dataset.value);
    if (!entry) return;
    current = entry;
    applyToTrigger(entry);
    // SC 3.2.2 — don't auto-submit; just refocus the input.
    input.setFocus?.();
    if (onChange) onChange(entry.value, entry);
  });

  function applyToTrigger(entry) {
    labelEl.textContent = entry.label;
    chip.textContent    = entry.badge ?? entry.label.charAt(0).toUpperCase();
    chip.setAttribute("kind", entry.chipKind ?? "brand");
    trigger.setAttribute("aria-label", `Search field: ${entry.label}`);
    input.placeholder = entry.placeholder ?? `Search by ${entry.label.toLowerCase()}`;
    input.setAttribute("aria-label", `Search text: ${entry.label}`);
  }

  return {
    getField: () => current?.value,
    getSpec:  () => current,
  };
}
