/* ---------------------------------------------------------------------------
   ResultsTable.js — accessible port of webroot5/5/js/ResultsTable.js.
   Semantic <table> / <thead> / <tbody> / <th> / <td> (no ARIA grid gymnastics),
   with the feature set from webroot5:
     - sortable columns (click or Enter/Space on header)
     - per-row action buttons (Zoom, Buffer, Adjoiners, Report, Tax Info, Permits)
     - client-side pagination
     - hidden OBJECTID/GLOBALID/Shape fields
     - priority/deprioritize field ordering
     - result count + Export CSV button

   Accessibility mirrored from webrootWCAG/src/DataTable.js:
     - <caption> describes the table
     - <th scope="col">, <th aria-sort> for sort state
     - Roving tabindex on rows; ArrowUp/Down, Home/End move focus; Enter/Space
       activates (fires onRowSelect)
     - Page-nav buttons are real <button>s
   --------------------------------------------------------------------------- */

const HIDDEN_FIELDS = /^(GLOBALID|GlobalID|Shape|SHAPE|Shape\.STArea|Shape\.STLength)$/i;

const GLOBAL_PRIORITY_FIELDS = [
  "REID", "LOCATION_ADDR", "FULL_ADDRESS", "PROPERTY_OWNER",
  "PIN",  "A_NUMBER", "PermitNum", "Permit_ID",
];

const GLOBAL_DEPRIORITIZED_FIELDS = [
  "OBJECTID", "OBJECTID_1",
  "Shape_Length", "Shape_Area", "Shape__Length", "Shape__Area",
  "st_area(shape)", "st_length(shape)",
];

const ACTION_CONFIGS = {
  parcels: [
    { key: "zoom",      label: "Zoom" },
    { key: "buffer",    label: "Buffer" },
    { key: "adjoiners", label: "Find Adjoiners" },
    { key: "report",    label: "Report" },
    { key: "taxinfo",   label: "Tax Info" },
  ],
  addresses: [
    { key: "zoom",    label: "Zoom" },
    { key: "permits", label: "Permits" },
  ],
  generic: [
    { key: "zoom", label: "Zoom" },
  ],
};

const ci = (s) => String(s).toLowerCase();

function reorderFields(fields, layerPriority = [], layerDeprio = []) {
  const layerPrioSet  = new Set(layerPriority.map(ci));
  const layerDeprioSet = new Set(layerDeprio.map(ci));

  const effectivePriority = [
    ...GLOBAL_PRIORITY_FIELDS.filter((n) => !layerDeprioSet.has(ci(n))),
    ...layerPriority,
  ];
  const effectiveDeprio = [
    ...GLOBAL_DEPRIORITIZED_FIELDS.filter((n) => !layerPrioSet.has(ci(n))),
    ...layerDeprio,
  ];

  const prioRank   = new Map(effectivePriority.map((n, i) => [ci(n), i]));
  const deprioRank = new Map(effectiveDeprio.map((n, i)   => [ci(n), i]));

  const priority = [];
  const deprioritized = [];
  const normal = [];
  for (const f of fields) {
    const n = ci(f.name);
    if (prioRank.has(n)) priority.push(f);
    else if (deprioRank.has(n)) deprioritized.push(f);
    else normal.push(f);
  }
  priority.sort((a, b) => prioRank.get(ci(a.name)) - prioRank.get(ci(b.name)));
  deprioritized.sort((a, b) => deprioRank.get(ci(a.name)) - deprioRank.get(ci(b.name)));
  return [...priority, ...normal, ...deprioritized];
}

export class ResultsTable {
  /**
   * @param {Object} options
   * @param {HTMLElement} options.container
   * @param {number} [options.pageSize=25]
   * @param {string} [options.layerType="generic"]
   * @param {string} [options.oidField="OBJECTID"]
   * @param {string} [options.captionText="Search results"]
   * @param {Function} [options.onAction]    (actionKey, id, feature) => void
   * @param {Function} [options.onRowSelect] (objectId, feature)       => void
   * @param {Function} [options.onExport]    ()                         => void
   */
  constructor({
    container,
    pageSize = 25,
    layerType = "generic",
    oidField = "OBJECTID",
    captionText = "Search results",
    onAction,
    onRowSelect,
    onExport,
  }) {
    this.container = container;
    this.pageSize = pageSize;
    this.layerType = layerType;
    this.oidField = oidField;
    this.captionText = captionText;
    this.onAction = onAction || (() => {});
    this.onRowSelect = onRowSelect || (() => {});
    this.onExport = onExport || null;

    this._features = [];
    this._fields = [];
    this._visibleFields = [];
    this._currentPage = 1;
    this._totalPages = 1;
    this._selectedObjectId = null;
    this._sortField = null;
    this._sortAsc = true;

    this._buildShell();
  }

  _buildShell() {
    this.container.replaceChildren();
    this.container.classList.add("results-panel");

    // Status bar: count + Export CSV button.
    this._statusEl = document.createElement("div");
    this._statusEl.className = "results-status";

    this._statusTextEl = document.createElement("span");
    this._statusTextEl.className = "results-status-text";
    this._statusTextEl.setAttribute("aria-live", "polite");
    this._statusTextEl.setAttribute("aria-atomic", "true");
    this._statusTextEl.textContent = "No results yet.";
    this._statusEl.appendChild(this._statusTextEl);

    if (this.onExport) {
      this._exportBtn = document.createElement("calcite-button");
      this._exportBtn.className = "results-export-btn";
      this._exportBtn.setAttribute("appearance", "outline");
      this._exportBtn.setAttribute("kind", "neutral");
      this._exportBtn.setAttribute("scale", "s");
      this._exportBtn.setAttribute("icon-start", "file-csv");
      this._exportBtn.textContent = "Export CSV";
      this._exportBtn.hidden = true;
      this._exportBtn.addEventListener("click", () => this.onExport());
      this._statusEl.appendChild(this._exportBtn);
    }

    this._tableWrapper = document.createElement("div");
    this._tableWrapper.className = "results-table-wrapper";

    this._paginationEl = document.createElement("nav");
    this._paginationEl.className = "results-pagination";
    this._paginationEl.setAttribute("aria-label", "Results pagination");

    this.container.append(this._statusEl, this._tableWrapper, this._paginationEl);
  }

  /**
   * Compat helper used by the CAV pipeline — lets a caller push the same
   * feature array the map is showing into the table, without a FeatureSet.
   * Keeps the DataTable-style API from webrootWCAG working.
   */
  setFeatures(features, options = {}) {
    this.load({
      features,
      fields: options.fields || this._fields,
      objectIdFieldName: options.oidField || this.oidField,
    }, options);
  }

  /** Load a FeatureSet (ArcGIS query result) into the table. */
  load(featureSet, options = {}) {
    if (options.layerType) this.layerType = options.layerType;
    if (options.oidField)  this.oidField  = options.oidField;
    this._features = featureSet.features || [];
    this._fields   = featureSet.fields || this._fields;
    if (featureSet.objectIdFieldName) this.oidField = featureSet.objectIdFieldName;

    const shown = (this._fields || []).filter((f) => !HIDDEN_FIELDS.test(f.name));
    this._visibleFields = reorderFields(
      shown,
      options.priorityFields,
      options.deprioritizedFields,
    );
    this._currentPage = 1;
    this._totalPages = Math.max(1, Math.ceil(this._features.length / this.pageSize));
    this._selectedObjectId = null;
    this._sortField = null;

    if (this._features.length === 0) {
      this._statusTextEl.textContent = "No features found.";
      if (this._exportBtn) this._exportBtn.hidden = true;
      this._tableWrapper.replaceChildren();
      this._paginationEl.replaceChildren();
      return;
    }

    this._statusTextEl.textContent =
      `${this._features.length} result${this._features.length === 1 ? "" : "s"}`;
    if (this._exportBtn) this._exportBtn.hidden = false;
    this._renderPage();
    this._renderPagination();
  }

  clear() {
    this._features = [];
    this._fields = [];
    this._visibleFields = [];
    this._currentPage = 1;
    this._totalPages = 1;
    this._selectedObjectId = null;
    this._statusTextEl.textContent = "No results yet.";
    if (this._exportBtn) this._exportBtn.hidden = true;
    this._tableWrapper.replaceChildren();
    this._paginationEl.replaceChildren();
  }

  getAllObjectIds() {
    return this._features.map((f) => f.attributes[this.oidField]);
  }

  getAllFeatures() {
    return this._features;
  }

  // ─── internal rendering ──────────────────────────────────────────────────

  _renderPage() {
    const start = (this._currentPage - 1) * this.pageSize;
    const end = Math.min(start + this.pageSize, this._features.length);
    const pageFeatures = this._features.slice(start, end);
    const actions = ACTION_CONFIGS[this.layerType] || ACTION_CONFIGS.generic;

    const table = document.createElement("table");
    table.className = "results-table a11y-table";

    const caption = document.createElement("caption");
    caption.textContent = this.captionText;
    table.appendChild(caption);

    // Header
    const thead = document.createElement("thead");
    const headerRow = document.createElement("tr");

    for (const action of actions) {
      const th = document.createElement("th");
      th.scope = "col";
      th.className = "action-col";
      th.textContent = action.label;
      headerRow.appendChild(th);
    }

    for (const field of this._visibleFields) {
      const th = document.createElement("th");
      th.scope = "col";
      th.className = "data-col";
      th.tabIndex = 0;
      th.dataset.field = field.name;
      th.textContent = field.alias || field.name;

      if (this._sortField === field.name) {
        th.setAttribute("aria-sort", this._sortAsc ? "ascending" : "descending");
      } else {
        th.setAttribute("aria-sort", "none");
      }

      const sortHandler = () => this._sortBy(field.name);
      th.addEventListener("click", sortHandler);
      th.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          sortHandler();
        }
      });
      headerRow.appendChild(th);
    }
    thead.appendChild(headerRow);
    table.appendChild(thead);

    // Body
    const tbody = document.createElement("tbody");
    pageFeatures.forEach((feature, idx) => {
      const objectId = feature.attributes[this.oidField];
      const tr = document.createElement("tr");
      tr.dataset.objectid = objectId;
      tr.dataset.index = String(idx);
      tr.tabIndex = idx === 0 ? 0 : -1; // roving tabindex

      if (objectId === this._selectedObjectId) {
        tr.classList.add("row-selected");
      }

      // Action cells
      for (const action of actions) {
        const td = document.createElement("td");
        td.className = "action-col";

        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = `action-btn action-${action.key}`;
        btn.textContent = action.label;
        btn.dataset.action = action.key;
        btn.dataset.objectid = objectId;

        if (action.key === "taxinfo" && feature.attributes.REID != null) {
          btn.dataset.parcelpk = feature.attributes.REID;
        }

        btn.addEventListener("click", (e) => {
          e.stopPropagation();
          const id = action.key === "taxinfo" ? btn.dataset.parcelpk : objectId;
          this.onAction(action.key, id, feature);
        });

        td.appendChild(btn);
        tr.appendChild(td);
      }

      // Data cells
      for (const field of this._visibleFields) {
        const td = document.createElement("td");
        td.className = "data-col";
        const val = feature.attributes[field.name];
        td.textContent = val == null ? "" : String(val);
        tr.appendChild(td);
      }

      tr.addEventListener("click", (e) => {
        if (e.target.closest(".action-btn")) return;
        this._selectRow(objectId, feature);
      });
      tr.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
          if (e.target.closest(".action-btn")) return;
          e.preventDefault();
          this._selectRow(objectId, feature);
        }
      });

      tbody.appendChild(tr);
    });

    tbody.addEventListener("keydown", (e) => this._onRowNavKey(e));
    table.appendChild(tbody);

    this._tableWrapper.replaceChildren(table);
  }

  _onRowNavKey(e) {
    const rows = Array.from(this._tableWrapper.querySelectorAll("tbody tr"));
    if (!rows.length) return;
    // Only react when a row itself has focus (not a nested action button).
    if (!rows.includes(document.activeElement)) return;
    const i = rows.indexOf(document.activeElement);

    let next = null;
    switch (e.key) {
      case "ArrowDown": next = rows[Math.min(i + 1, rows.length - 1)]; break;
      case "ArrowUp":   next = rows[Math.max(i - 1, 0)]; break;
      case "Home":      next = rows[0]; break;
      case "End":       next = rows[rows.length - 1]; break;
      default: return;
    }
    e.preventDefault();
    rows.forEach((r) => { r.tabIndex = -1; });
    next.tabIndex = 0;
    next.focus();
  }

  _renderPagination() {
    this._paginationEl.replaceChildren();
    if (this._totalPages <= 1) return;

    const createBtn = (label, page, disabled) => {
      const b = document.createElement("calcite-button");
      b.className = "pagination-btn";
      b.setAttribute("appearance", "outline");
      b.setAttribute("kind", "neutral");
      b.setAttribute("scale", "s");
      b.textContent = label;
      if (disabled) b.setAttribute("disabled", "");
      b.addEventListener("click", () => {
        if (disabled) return;
        this._currentPage = page;
        this._renderPage();
        this._renderPagination();
      });
      return b;
    };

    const isFirst = this._currentPage === 1;
    const isLast  = this._currentPage === this._totalPages;

    this._paginationEl.append(
      createBtn("First", 1, isFirst),
      createBtn("Prev", this._currentPage - 1, isFirst),
    );

    const pageLabel = document.createElement("span");
    pageLabel.className = "pagination-label";
    pageLabel.textContent = `Page ${this._currentPage} of ${this._totalPages}`;
    this._paginationEl.appendChild(pageLabel);

    this._paginationEl.append(
      createBtn("Next", this._currentPage + 1, isLast),
      createBtn("Last", this._totalPages, isLast),
    );
  }

  _selectRow(objectId, feature) {
    const prev = this._tableWrapper.querySelector(".row-selected");
    if (prev) prev.classList.remove("row-selected");

    this._selectedObjectId = objectId;
    const row = this._tableWrapper.querySelector(`tr[data-objectid="${objectId}"]`);
    if (row) row.classList.add("row-selected");

    this.onRowSelect(objectId, feature);
  }

  _sortBy(fieldName) {
    if (this._sortField === fieldName) {
      this._sortAsc = !this._sortAsc;
    } else {
      this._sortField = fieldName;
      this._sortAsc = true;
    }
    this._features.sort((a, b) => {
      const va = a.attributes[fieldName];
      const vb = b.attributes[fieldName];
      if (va == null && vb == null) return 0;
      if (va == null) return 1;
      if (vb == null) return -1;
      if (typeof va === "number" && typeof vb === "number") {
        return this._sortAsc ? va - vb : vb - va;
      }
      const cmp = String(va).localeCompare(String(vb));
      return this._sortAsc ? cmp : -cmp;
    });
    this._currentPage = 1;
    this._renderPage();
    this._renderPagination();
  }
}
