/**
 * QueryEngine.js
 * Modern query execution utility for ArcGIS JS SDK 5 (@arcgis/core).
 * Extracted from GoMaps legacy app — no Dojo, no jQuery.
 *
 * Usage:
 *   import { queryByWhere, queryByObjectIds, queryByGeometry, queryForDistinctValues } from './QueryEngine.js';
 *
 *   const results = await queryByWhere(layerUrl, "PIN LIKE '1234%'", { outFields: ["*"], returnGeometry: true });
 */

import * as query from "@arcgis/core/rest/query.js";
import Query from "@arcgis/core/rest/support/Query.js";

/**
 * Execute a query against a map service layer URL using a WHERE clause.
 *
 * @param {string} layerUrl - Full URL to the layer endpoint (e.g. .../MapServer/89)
 * @param {string} where - SQL WHERE clause
 * @param {Object} [options]
 * @param {string[]} [options.outFields=["*"]] - Fields to return
 * @param {boolean} [options.returnGeometry=false]
 * @param {number} [options.maxAllowableOffset]
 * @param {Object} [options.outSpatialReference] - e.g. { wkid: 102100 }
 * @returns {Promise<FeatureSet>}
 */
export async function queryByWhere(layerUrl, where, options = {}) {
  const q = new Query({
    where,
    outFields: options.outFields ?? ["*"],
    returnGeometry: options.returnGeometry ?? false,
    ...(options.maxAllowableOffset != null && { maxAllowableOffset: options.maxAllowableOffset }),
    ...(options.outSpatialReference && { outSpatialReference: options.outSpatialReference }),
  });
  return query.executeQueryJSON(layerUrl, q);
}

/**
 * Query features by a list of OBJECTIDs.
 *
 * @param {string} layerUrl
 * @param {number[]} objectIds
 * @param {Object} [options]
 * @param {string[]} [options.outFields=["OBJECTID"]]
 * @param {boolean} [options.returnGeometry=true]
 * @param {Object} [options.outSpatialReference]
 * @returns {Promise<FeatureSet>}
 */
export async function queryByObjectIds(layerUrl, objectIds, options = {}) {
  const oidField = options.oidField ?? "OBJECTID";
  const where = `${oidField} IN (${objectIds.join(",")})`;
  const q = new Query({
    where,
    outFields: options.outFields ?? [oidField],
    returnGeometry: options.returnGeometry ?? true,
    ...(options.outSpatialReference && { outSpatialReference: options.outSpatialReference }),
  });
  return query.executeQueryJSON(layerUrl, q);
}

/**
 * Query features that intersect a geometry (point, extent, polygon, etc.).
 *
 * @param {string} layerUrl
 * @param {Geometry} geometry - An @arcgis/core Geometry instance
 * @param {Object} [options]
 * @param {string[]} [options.outFields=["OBJECTID"]]
 * @param {boolean} [options.returnGeometry=true]
 * @param {string} [options.spatialRelationship="intersects"]
 * @returns {Promise<FeatureSet>}
 */
export async function queryByGeometry(layerUrl, geometry, options = {}) {
  const q = new Query({
    geometry,
    spatialRelationship: options.spatialRelationship ?? "intersects",
    outFields: options.outFields ?? ["OBJECTID"],
    returnGeometry: options.returnGeometry ?? true,
  });
  return query.executeQueryJSON(layerUrl, q);
}

/**
 * Get distinct values for a field. Used by the query builder UI to populate
 * the "Distinct Values" dropdown.
 *
 * @param {string} layerUrl
 * @param {string} fieldName
 * @param {string} [where="1=1"]
 * @returns {Promise<any[]>} Array of unique values
 */
export async function queryForDistinctValues(layerUrl, fieldName, where = "1=1") {
  const q = new Query({
    where,
    outFields: [fieldName],
    returnDistinctValues: true,
    returnGeometry: false,
    orderByFields: [fieldName],
  });
  const results = await query.executeQueryJSON(layerUrl, q);
  return results.features
    .map((f) => f.attributes[fieldName])
    .filter((v) => v != null);
}

/**
 * Fetch field metadata for a layer (name, alias, type).
 * Useful for building query builder UIs.
 *
 * @param {string} layerUrl
 * @returns {Promise<Array<{name: string, alias: string, type: string}>>}
 */
export async function fetchLayerFields(layerUrl) {
  const res = await fetch(`${layerUrl}?f=json`);
  const info = await res.json();
  if (!info.fields) return [];
  return info.fields.map((f) => ({
    name: f.name,
    alias: f.alias || f.name,
    type: f.type,
  }));
}
