/**
 * ExportCSV.js
 * Clean CSV export from a FeatureSet or an HTML table element.
 * Extracted from GoMaps legacy exportToExcel.js — no IE hacks, no jQuery.
 *
 * Usage:
 *   import { exportFeatureSetToCSV, exportTableElementToCSV } from './ExportCSV.js';
 *
 *   // From a FeatureSet (query results)
 *   exportFeatureSetToCSV(featureSet, 'parcels.csv');
 *
 *   // From a rendered <table> element
 *   exportTableElementToCSV(document.getElementById('resultsTable'), 'export.csv');
 */

/**
 * Export an ArcGIS FeatureSet directly to a CSV download.
 *
 * @param {FeatureSet} featureSet - Result from a query (has .fields and .features)
 * @param {string} [filename="export.csv"]
 */
export function exportFeatureSetToCSV(featureSet, filename = "export.csv") {
  const fields = featureSet.fields || [];
  const features = featureSet.features || [];

  // Header row — use aliases when available
  const headers = fields.map((f) => f.alias || f.name);

  // Data rows
  const rows = features.map((feature) =>
    fields.map((f) => {
      const val = feature.attributes[f.name];
      return val == null ? "" : String(val);
    })
  );

  const csvContent = buildCSV(headers, rows);
  downloadCSV(csvContent, filename);
}

/**
 * Export an HTML <table> element to a CSV download.
 *
 * @param {HTMLTableElement} tableEl
 * @param {string} [filename="export.csv"]
 */
export function exportTableElementToCSV(tableEl, filename = "export.csv") {
  const headers = [];
  const rows = [];

  // Grab headers
  const thRow = tableEl.querySelector("thead tr");
  if (thRow) {
    for (const th of thRow.querySelectorAll("th")) {
      // Skip action columns (Zoom, Buffer, etc.)
      if (!th.classList.contains("action-col")) {
        headers.push(th.textContent.trim());
      }
    }
  }

  // Grab data rows
  for (const tr of tableEl.querySelectorAll("tbody tr")) {
    const cells = [];
    for (const td of tr.querySelectorAll("td")) {
      if (!td.classList.contains("action-col")) {
        cells.push(td.textContent.trim());
      }
    }
    if (cells.length > 0) rows.push(cells);
  }

  const csvContent = buildCSV(headers, rows);
  downloadCSV(csvContent, filename);
}

/**
 * Build a CSV string from headers and row arrays.
 * Handles quoting and escaping double quotes.
 */
function buildCSV(headers, rows) {
  const escapeCell = (val) => {
    const str = String(val);
    if (str.includes('"') || str.includes(",") || str.includes("\n")) {
      return '"' + str.replace(/"/g, '""') + '"';
    }
    return str;
  };

  const lines = [];
  lines.push(headers.map(escapeCell).join(","));
  for (const row of rows) {
    lines.push(row.map(escapeCell).join(","));
  }
  return lines.join("\r\n");
}

/**
 * Trigger a file download in the browser.
 */
function downloadCSV(csvContent, filename) {
  const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}
