/**
 * TableActions.js
 * All row-level action button handlers extracted from GoMaps legacy main.js.
 * Modernized for ArcGIS JS SDK 5 (@arcgis/core) — no Dojo, no jQuery.
 *
 * Each function is standalone. Pass in what it needs — no global state.
 *
 * Usage:
 *   import { zoomToFeature, bufferFeature, findAdjoiners, openParcelReport, openTaxInfo, openPermits } from './TableActions.js';
 */

import * as query from "@arcgis/core/rest/query.js";
import Query from "@arcgis/core/rest/support/Query.js";
import Graphic from "@arcgis/core/Graphic.js";
import * as geodesicBufferOperator from "@arcgis/core/geometry/operators/geodesicBufferOperator.js";
import * as unionOperator from "@arcgis/core/geometry/operators/unionOperator.js";
import SimpleFillSymbol from "@arcgis/core/symbols/SimpleFillSymbol.js";
import SimpleLineSymbol from "@arcgis/core/symbols/SimpleLineSymbol.js";
import SimpleMarkerSymbol from "@arcgis/core/symbols/SimpleMarkerSymbol.js";

// geodesicBufferOperator is WASM-backed and must be loaded before use.
// unionOperator is synchronous and needs no preload.
let _operatorsReady;
function ensureOperatorsLoaded() {
  if (!_operatorsReady) _operatorsReady = geodesicBufferOperator.load();
  return _operatorsReady;
}

// ─── Default Symbols (override via config) ──────────────────────────────────

const DEFAULT_ZOOM_SYMBOLS = {
  point: new SimpleMarkerSymbol({
    style: "circle",
    size: 10,
    color: [0, 255, 0, 0],
    outline: { color: [255, 255, 0], width: 3 },
  }),
  polyline: new SimpleLineSymbol({
    style: "solid",
    color: [255, 255, 0],
    width: 3,
  }),
  polygon: new SimpleFillSymbol({
    style: "solid",
    color: [255, 255, 0, 0],
    outline: { color: [255, 255, 0], width: 2 },
  }),
};

const DEFAULT_BUFFER_SYMBOL = new SimpleFillSymbol({
  style: "solid",
  color: [255, 0, 0, 0.15],
  outline: { color: [255, 0, 0], width: 2 },
});

const DEFAULT_SELECT_SYMBOLS = {
  point: new SimpleMarkerSymbol({
    style: "circle",
    size: 9,
    color: [0, 200, 255, 0.6],
    outline: { color: [0, 120, 200], width: 2 },
  }),
  polyline: new SimpleLineSymbol({
    style: "solid",
    color: [0, 120, 200],
    width: 3,
  }),
  polygon: new SimpleFillSymbol({
    style: "solid",
    color: [0, 200, 255, 0.25],
    outline: { color: [0, 120, 200], width: 2 },
  }),
};

/**
 * Render the "selection set" onto a GraphicsLayer: one graphic per result feature.
 * This is the multi-feature result of a search / query builder run — distinct from
 * the single-feature `highlight` used by zoomToFeature (identify-style).
 * Clears any existing graphics on the layer first.
 *
 * @param {GraphicsLayer} selectionLayer
 * @param {Feature[]} features - Array of features (each with .geometry + .attributes)
 * @param {Object} [symbols] - Override { point, polyline, polygon }
 */
export function selectFeatures(selectionLayer, features, symbols) {
  selectionLayer.removeAll();
  if (!features || !features.length) return;
  const sym = { ...DEFAULT_SELECT_SYMBOLS, ...symbols };
  const graphics = [];
  for (const f of features) {
    if (!f.geometry) continue;
    const symbol = sym[f.geometry.type] || sym.polygon;
    graphics.push(new Graphic({ geometry: f.geometry, symbol, attributes: f.attributes }));
  }
  selectionLayer.addMany(graphics);
}

// ─── Zoom ───────────────────────────────────────────────────────────────────

/**
 * Zoom the MapView to a single feature by OBJECTID.
 * Queries the feature's geometry, highlights it, and zooms.
 *
 * @param {MapView} view - The SDK 5 MapView
 * @param {string} layerUrl - Full URL to the map service layer
 * @param {number} objectId - The OBJECTID to zoom to
 * @param {GraphicsLayer} highlightLayer - A GraphicsLayer to draw the zoom highlight on
 * @param {Object} [symbols] - Override zoom symbols { point, polyline, polygon }
 */
export async function zoomToFeature(view, layerUrl, objectId, highlightLayer, symbols, oidField = "OBJECTID") {
  const sym = { ...DEFAULT_ZOOM_SYMBOLS, ...symbols };
  highlightLayer.removeAll();

  const q = new Query({
    where: `${oidField} = ${objectId}`,
    returnGeometry: true,
    outFields: ["*"],
    outSpatialReference: view.spatialReference,
  });
  const results = await query.executeQueryJSON(layerUrl, q);
  if (!results.features.length) return;

  const feature = results.features[0];
  const geometry = feature.geometry;
  const symbol = sym[geometry.type] || sym.polygon;

  highlightLayer.add(new Graphic({ geometry, symbol }));

  if (geometry.type === "point") {
    await view.goTo({ target: geometry, zoom: 19 });
  } else {
    await view.goTo(geometry.extent.expand(3));
  }

  return feature;
}

// ─── Buffer ─────────────────────────────────────────────────────────────────

/**
 * Buffer a single feature and optionally query another layer within the buffer.
 * Uses client-side geometryEngine — no GeometryServer required.
 *
 * @param {Object} params
 * @param {string} params.sourceLayerUrl - Layer URL of the feature to buffer
 * @param {number} params.objectId - OBJECTID of the feature to buffer
 * @param {number} params.distance - Buffer distance
 * @param {string} [params.unit="feet"] - "feet", "meters", "miles", "kilometers", etc.
 * @param {GraphicsLayer} params.bufferLayer - GraphicsLayer to draw the buffer ring on
 * @param {string} [params.queryLayerUrl] - If provided, features from this layer within the buffer are returned
 * @param {SimpleFillSymbol} [params.bufferSymbol]
 * @param {string} [params.oidField="OBJECTID"]
 * @returns {Promise<{bufferGeometry: Polygon, features?: Feature[]}>}
 */
export async function bufferFeature({
  sourceLayerUrl,
  objectId,
  distance,
  unit = "feet",
  view,
  bufferLayer,
  queryLayerUrl,
  bufferSymbol,
  oidField = "OBJECTID",
}) {
  const q = new Query({
    where: `${oidField} = ${objectId}`,
    returnGeometry: true,
    outFields: ["*"],
    ...(view && { outSpatialReference: view.spatialReference }),
  });
  const sourceResults = await query.executeQueryJSON(sourceLayerUrl, q);
  if (!sourceResults.features.length) throw new Error("Feature not found");

  await ensureOperatorsLoaded();
  const bufferGeometry = geodesicBufferOperator.execute(
    sourceResults.features[0].geometry,
    distance,
    { unit }
  );

  bufferLayer.removeAll();
  bufferLayer.add(
    new Graphic({
      geometry: bufferGeometry,
      symbol: bufferSymbol || DEFAULT_BUFFER_SYMBOL,
    })
  );

  let features;
  if (queryLayerUrl) {
    const bq = new Query({
      geometry: bufferGeometry,
      spatialRelationship: "intersects",
      returnGeometry: true,
      outFields: [oidField],
    });
    const bufferQueryResults = await query.executeQueryJSON(queryLayerUrl, bq);
    features = bufferQueryResults.features;
  }

  return { bufferGeometry, features };
}

/**
 * Buffer ALL supplied geometries (unioned) and optionally query within.
 * Uses client-side geometryEngine.
 *
 * @param {Object} params
 * @param {Geometry[]} params.geometries - Array of feature geometries to buffer
 * @param {number} params.distance
 * @param {string} [params.unit="feet"]
 * @param {GraphicsLayer} params.bufferLayer
 * @param {string} [params.queryLayerUrl]
 * @param {SimpleFillSymbol} [params.bufferSymbol]
 * @param {string} [params.oidField="OBJECTID"]
 * @returns {Promise<{bufferGeometry: Polygon, features?: Feature[]}>}
 */
export async function bufferAllFeatures({
  geometries,
  distance,
  unit = "feet",
  bufferLayer,
  queryLayerUrl,
  bufferSymbol,
  oidField = "OBJECTID",
}) {
  await ensureOperatorsLoaded();
  const unioned = unionOperator.executeMany(geometries);
  const bufferGeometry = geodesicBufferOperator.execute(unioned, distance, { unit });

  bufferLayer.removeAll();
  bufferLayer.add(
    new Graphic({
      geometry: bufferGeometry,
      symbol: bufferSymbol || DEFAULT_BUFFER_SYMBOL,
    })
  );

  let features;
  if (queryLayerUrl) {
    const bq = new Query({
      geometry: bufferGeometry,
      spatialRelationship: "intersects",
      returnGeometry: true,
      outFields: [oidField],
    });
    const bufferQueryResults = await query.executeQueryJSON(queryLayerUrl, bq);
    features = bufferQueryResults.features;
  }

  return { bufferGeometry, features };
}

// ─── Find Adjoiners ─────────────────────────────────────────────────────────

/**
 * Find parcels adjoining (touching) a given parcel.
 * Does a tiny 1-foot buffer, then queries the parcel layer for intersecting features.
 *
 * @param {Object} params
 * @param {string} params.geometryServiceUrl
 * @param {Geometry} params.parcelGeometry - The geometry of the source parcel
 * @param {string} params.parcelLayerUrl - URL to the parcels layer
 * @param {MapView} params.view
 * @param {GraphicsLayer} params.bufferLayer
 * @returns {Promise<Feature[]>} Adjoining parcel features
 */
export async function findAdjoiners({
  parcelGeometry,
  parcelLayerUrl,
  bufferLayer,
  oidField = "OBJECTID",
}) {
  await ensureOperatorsLoaded();
  const bufferGeometry = geodesicBufferOperator.execute(parcelGeometry, 1, { unit: "feet" });

  bufferLayer.removeAll();
  bufferLayer.add(
    new Graphic({
      geometry: bufferGeometry,
      symbol: DEFAULT_BUFFER_SYMBOL,
    })
  );

  const q = new Query({
    geometry: bufferGeometry,
    spatialRelationship: "intersects",
    returnGeometry: true,
    outFields: [oidField],
  });
  const results = await query.executeQueryJSON(parcelLayerUrl, q);
  return results.features;
}

// ─── Report ─────────────────────────────────────────────────────────────────

/**
 * Open a parcel report in a new browser tab.
 * Builds the URL with all the parameters the legacy report page expects.
 *
 * @param {Object} params
 * @param {number} params.objectId - OBJECTID of the parcel
 * @param {string} params.layerUrl - Full URL to the parcels layer
 * @param {string} params.reportBaseUrl - Base URL to the report page (e.g. "Reports/UserDefined/parcelReport.html")
 * @param {number[]} params.visibleLayers - Array of currently visible layer IDs
 * @param {string} params.basemap - Current basemap name
 * @param {Extent} [params.extent] - Map extent to show in the report. If not provided, builds from feature.
 * @param {boolean} [params.showAerials=false]
 * @param {boolean} [params.showHillshade=false]
 */
export function openParcelReport({
  objectId,
  layerUrl,
  reportBaseUrl,
  visibleLayers,
  basemap,
  extent,
  showAerials = false,
  showHillshade = false,
}) {
  const params = new URLSearchParams({
    objectID: objectId,
    url: layerUrl,
    visLayers: visibleLayers.join(","),
    aerial: showAerials,
    hillShade: showHillshade,
    basemap: basemap,
  });

  if (extent) {
    params.set("bbox", `${extent.xmin},${extent.ymin},${extent.xmax},${extent.ymax}`);
  }

  window.open(`${reportBaseUrl}?${params.toString()}`);
}

/**
 * Open a generic feature report (non-parcel layers).
 * Same interface as openParcelReport — the report page handles the difference.
 */
export const openFeatureReport = openParcelReport;

// ─── Tax Info ───────────────────────────────────────────────────────────────

/**
 * Open a tax info page for a parcel.
 *
 * @param {string} parcelpk - The REID or parcel key for the tax lookup
 * @param {string} [taxBaseUrl="https://taxcama.dconc.gov/camapwa/PropertySummary.aspx"] - Tax site base URL
 */
export function openTaxInfo(parcelpk, taxBaseUrl = "https://taxcama.dconc.gov/camapwa/PropertySummary.aspx") {
  window.open(`${taxBaseUrl}?PARCELPK=${parcelpk}`);
}

// ─── Permits ────────────────────────────────────────────────────────────────

/**
 * Look up permits for an address feature.
 * Queries the feature to get address components, then opens the permits page.
 *
 * @param {string} layerUrl - URL to the address layer
 * @param {number} objectId - OBJECTID of the address feature
 * @param {string} [permitsBaseUrl] - Base URL for permits search
 */
export async function openPermits(layerUrl, objectId, permitsBaseUrl = "https://taxinfo.hendersoncountync.org/pnipwa/Search/SearchResults.aspx", oidField = "OBJECTID") {
  const q = new Query({
    where: `${oidField} = ${objectId}`,
    returnGeometry: false,
    outFields: ["HOUSENUM", "STREETNAME", "STREETTYPE"],
  });
  const results = await query.executeQueryJSON(layerUrl, q);
  if (!results.features.length) return;

  const attrs = results.features[0].attributes;
  const params = new URLSearchParams({
    searchtype: "property",
    addressnum: attrs.HOUSENUM || "",
    addressname: ` ${attrs.STREETNAME || ""} ${attrs.STREETTYPE || ""}  `,
    cmd: "search",
  });

  window.open(`${permitsBaseUrl}?${params.toString()}`);
}
