import FeatureLayer from "@arcgis/core/layers/FeatureLayer.js";
import TileLayer from "@arcgis/core/layers/TileLayer.js";
import MapImageLayer from "@arcgis/core/layers/MapImageLayer.js";
import VectorTileLayer from "@arcgis/core/layers/VectorTileLayer.js";

const LAYER_CTORS = {
  feature: FeatureLayer,
  tile: TileLayer,
  mapImage: MapImageLayer,
  vectorTile: VectorTileLayer,
};

/**
 * LayerRegistry — single source of truth for every layer in the app.
 *
 * Widgets (search, query builder, layer list, drill, popup) ask the registry
 * for layers by id or by capability; they never reach into app-level globals.
 *
 * A layer *config* is the declarative definition (imported from layers/*.js).
 * A layer *instance* is the @arcgis/core Layer object, lazily built from the
 * config on first request (or eagerly when config.essential is true).
 */
class LayerRegistryImpl {
  constructor() {
    this.configs = new Map();
    this.instances = new Map();
  }

  register(config) {
    if (!config?.id) throw new Error("LayerRegistry: config.id is required");
    if (this.configs.has(config.id)) {
      throw new Error(`LayerRegistry: duplicate layer id "${config.id}"`);
    }
    const normalized = { role: "operational", queryable: false, ...config };
    this.configs.set(normalized.id, normalized);
    return normalized;
  }

  getConfig(id) {
    return this.configs.get(id) ?? null;
  }

  getInstance(id) {
    if (this.instances.has(id)) return this.instances.get(id);
    const config = this.configs.get(id);
    if (!config) return null;
    const layer = this.#build(config);
    this.instances.set(id, layer);
    return layer;
  }

  allConfigs() {
    return [...this.configs.values()].sort(
      (a, b) => (a.drawOrder ?? 0) - (b.drawOrder ?? 0)
    );
  }

  byCategory(category) {
    return this.allConfigs().filter((c) => c.category === category);
  }

  byRole(role) {
    return this.allConfigs().filter((c) => c.role === role);
  }

  queryable() {
    return this.allConfigs().filter((c) => c.queryable);
  }

  essential() {
    return this.allConfigs().filter((c) => c.essential);
  }

  /** Materialize instances for every layer flagged `essential: true`. */
  buildEssential() {
    return this.essential().map((c) => this.getInstance(c.id));
  }

  #build(config) {
    const Ctor = LAYER_CTORS[config.layerType];
    if (!Ctor) {
      throw new Error(`LayerRegistry: unknown layerType "${config.layerType}" for id "${config.id}"`);
    }
    const popupTemplate =
      typeof config.popupTemplate === "function" ? config.popupTemplate() : config.popupTemplate;

    return new Ctor({
      id: config.id,
      url: config.url,
      title: config.title,
      visible: config.defaultVisible ?? false,
      ...(popupTemplate && { popupTemplate }),
      ...(config.constructorOptions ?? {}),
    });
  }
}

export const LayerRegistry = new LayerRegistryImpl();

// ─── Auto-registration ─────────────────────────────────────────────────────
// Every JS file in ./layers/ is picked up automatically at build time via
// Vite's import.meta.glob. Drop a new layer config into that folder and it
// appears in the registry — no edits here required.
const layerModules = import.meta.glob("./layers/*.js", { eager: true });
for (const [path, mod] of Object.entries(layerModules)) {
  if (path.endsWith("/types.js")) continue;
  if (!mod.default) {
    console.warn(`LayerRegistry: ${path} has no default export; skipping.`);
    continue;
  }
  LayerRegistry.register(mod.default);
}
