/* ---------------------------------------------------------------------------
   Accessible Map Starter — app.js
   Ported from webroot5/5/js/app.js onto the Calcite + WCAG shell.

   What this file wires together:
     - LayerRegistry + layer configs     (src/LayerRegistry.js, src/layers/*.js)
     - QueryEngine queries               (src/QueryEngine.js)
     - Per-row actions                   (src/TableActions.js)
     - CSV export                        (src/ExportCSV.js)
     - FieldPicker (Calcite dropdown)    (src/FieldPicker.js)
     - LayerList (calcite-list)          (src/LayerList.js)
     - QueryBuilder (Calcite form)       (src/QueryBuilder.js)
     - ResultsTable (semantic <table>)   (src/ResultsTable.js)

   WCAG contract preserved from the starter:
     - view.aria label + description                           (SC 1.3.1, 2.4.6, 4.1.2)
     - skip links in index.html                                (SC 2.4.1)
     - prefers-reduced-motion gating                           (SC 2.3.3, 2.2.2)
     - Live-region announcements for zoom / search / errors    (SC 1.1.1, 4.1.3)
     - CAV pipeline: ONE query result drives both the map's
       definitionExpression and the results table — they cannot drift.
   --------------------------------------------------------------------------- */

import "@arcgis/core/assets/esri/themes/light/main.css";

import esriConfig from "@arcgis/core/config.js";
esriConfig.assetsPath = new URL("assets", document.baseURI).href;

import Map from "@arcgis/core/Map.js";
import Basemap from "@arcgis/core/Basemap.js";
import MapView from "@arcgis/core/views/MapView.js";
import GraphicsLayer from "@arcgis/core/layers/GraphicsLayer.js";
import FeatureLayer from "@arcgis/core/layers/FeatureLayer.js";
import VectorTileLayer from "@arcgis/core/layers/VectorTileLayer.js";
import * as reactiveUtils from "@arcgis/core/core/reactiveUtils.js";
import "@arcgis/map-components/components/arcgis-legend";

import { LayerRegistry } from "./LayerRegistry.js";
import { queryByWhere, queryByObjectIds } from "./QueryEngine.js";
import { ResultsTable } from "./ResultsTable.js";
import { QueryBuilder } from "./QueryBuilder.js";
import { LayerList } from "./LayerList.js";
import { initFieldPicker } from "./FieldPicker.js";
import {
  zoomToFeature, bufferFeature, findAdjoiners, selectFeatures,
  openParcelReport, openTaxInfo, openPermits,
} from "./TableActions.js";
import { exportFeatureSetToCSV } from "./ExportCSV.js";

// ===========================================================================
//  Config
// ===========================================================================

const CONFIG = {
  reportBaseUrl: "Reports/UserDefined/parcelReport.html",
};

const GRAYBASE_BACKGROUND = "https://tiles.arcgis.com/tiles/G5vR3cOjh6g2Ed8E/arcgis/rest/services/Graybase_Background/VectorTileServer";
const GRAYBASE_ROADS_URL  = "https://tiles.arcgis.com/tiles/G5vR3cOjh6g2Ed8E/arcgis/rest/services/Graybase_Roads/VectorTileServer";
const GRAYBASE_LABELS_URL = "https://tiles.arcgis.com/tiles/G5vR3cOjh6g2Ed8E/arcgis/rest/services/Graybase_Labels/VectorTileServer";
const DEVELOPMENT_TIERS_URL = "https://services2.arcgis.com/G5vR3cOjh6g2Ed8E/arcgis/rest/services/Planning/FeatureServer/5";
const ALL_DEV_CASES     = "https://services2.arcgis.com/G5vR3cOjh6g2Ed8E/arcgis/rest/services/Planning/FeatureServer/17";
const BUILDING_PERMITS  = "https://services2.arcgis.com/G5vR3cOjh6g2Ed8E/arcgis/rest/services/Inspections/FeatureServer/12";

const INITIAL_CENTER = [-78.9, 35.99];
const INITIAL_ZOOM   = 12;

const MAP_ARIA_LABEL =
  "Interactive map of Durham, North Carolina parcels";
const MAP_ARIA_DESCRIPTION =
  "Map shows Durham County parcels and related overlays. " +
  "Use arrow keys to pan, plus and minus to zoom, and N to orient north. " +
  "Press Tab to move between map widgets. " +
  "Results from the search bar and the query builder appear in the data table, " +
  "where each row can be activated to zoom the map.";

// ===========================================================================
//  Live-region announcements
// ===========================================================================

const politeRegion    = document.getElementById("aria-live-polite");
const assertiveRegion = document.getElementById("aria-live-assertive");

function announce(text, { assertive = false } = {}) {
  const region = assertive ? assertiveRegion : politeRegion;
  region.textContent = "";
  // eslint-disable-next-line no-unused-expressions
  region.offsetHeight;
  region.textContent = text;
}

// ===========================================================================
//  Reduced motion
// ===========================================================================

const prefersReducedMotion =
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

// ===========================================================================
//  Map composition (from LayerRegistry)
// ===========================================================================

const parcelsConfig   = LayerRegistry.getConfig("parcels");
const addressesConfig = LayerRegistry.getConfig("addresses");
const parcelsLayerUrl = parcelsConfig.url;
const addressLayerUrl = addressesConfig.url;
const PARCELS_OID     = parcelsConfig.oidField;
const ADDRESSES_OID   = addressesConfig.oidField;

// Development Tiers isn't in the layer registry yet — manual for now.
const devTiersLayer = new FeatureLayer({
  url: DEVELOPMENT_TIERS_URL,
  title: "Development Tiers",
  outFields: ["*"],
  opacity: 0.55,
  popupEnabled: true,
  visible: false,
});

const selectionLayer = new GraphicsLayer({ title: "Selection", listMode: "hide" });
const highlightLayer = new GraphicsLayer({ title: "Highlight", listMode: "hide" });
const bufferLayer    = new GraphicsLayer({ title: "Buffers",   listMode: "hide" });

const durhamGrayBasemap = new Basemap({
  title: "Durham Gray Basemap",
  baseLayers: [
    new VectorTileLayer({ url: GRAYBASE_BACKGROUND }),
    new VectorTileLayer({ url: GRAYBASE_ROADS_URL }),
    new VectorTileLayer({ url: GRAYBASE_LABELS_URL }),
  ],
});

const registryLayers = LayerRegistry
  .allConfigs()
  .filter((c) => c.role === "operational" && c.essential)
  .map((c) => LayerRegistry.getInstance(c.id));

const map = new Map({
  basemap: durhamGrayBasemap,
  layers: [...registryLayers, devTiersLayer, bufferLayer, selectionLayer, highlightLayer],
});

const view = new MapView({
  container: "viewDiv",
  map,
  center: INITIAL_CENTER,
  zoom: INITIAL_ZOOM,
  animationsEnabled: !prefersReducedMotion,
});

view.when(() => {
  view.aria = {
    label: MAP_ARIA_LABEL,
    description: MAP_ARIA_DESCRIPTION,
  };
  const host = document.getElementById("viewDiv");
  host.setAttribute("aria-label", MAP_ARIA_LABEL);
  announce("Map loaded. Run a search or open the query builder to populate the table.");
});

// Announce zoom changes (debounced to avoid flooding SR on pan/zoom).
let zoomAnnounceTimer = null;
reactiveUtils.watch(
  () => view.zoom,
  (z) => {
    clearTimeout(zoomAnnounceTimer);
    zoomAnnounceTimer = setTimeout(() => {
      announce(`Zoom level ${Math.round(z)}.`);
    }, 600);
  },
);

// ===========================================================================
//  Widgets: Legend (web component) + custom LayerList
// ===========================================================================

// Bind the <arcgis-legend> element (declared in index.html) to our view.
document.getElementById("legend-widget").view = view;

// eslint-disable-next-line no-new
new LayerList({
  container: document.getElementById("layer-list-container"),
  registry: LayerRegistry,
  map,
});

// ===========================================================================
//  Results table + action pipeline
// ===========================================================================

let lastFeatureSet = null;
let lastLayerConfig = parcelsConfig;

const table = new ResultsTable({
  container: document.getElementById("data-table-host"),
  pageSize: 25,
  layerType: parcelsConfig.actionType,
  oidField: PARCELS_OID,
  captionText: "Search and query results. Activate a row to zoom the map.",

  onRowSelect: async (objectId, feature) => {
    const layerCfg = lastLayerConfig || parcelsConfig;
    const addr  = feature?.attributes?.LOCATION_ADDR?.trim()
              || feature?.attributes?.FULL_ADDRESS?.trim();
    const owner = feature?.attributes?.PROPERTY_OWNER?.trim();
    const label = addr || owner || `${layerCfg.title} feature`;
    announce(`Zooming to ${label}.`);
    try {
      await zoomToFeature(
        view,
        layerCfg.queryUrl || layerCfg.url,
        objectId,
        highlightLayer,
        undefined,
        layerCfg.oidField || "OBJECTID",
      );
    } catch (err) {
      console.error("Row select failed:", err);
      announce("Could not zoom to that feature.", { assertive: true });
    }
  },

  onAction: async (action, id, feature) => {
    try {
      switch (action) {
        case "zoom":
          await zoomToFeature(view, parcelsLayerUrl, id, highlightLayer, undefined, PARCELS_OID);
          break;

        case "buffer": {
          const distance = prompt("Buffer distance (feet):", "100");
          if (!distance) return;
          const { features } = await bufferFeature({
            sourceLayerUrl: parcelsLayerUrl,
            objectId: id,
            distance: Number(distance),
            unit: "feet",
            view,
            bufferLayer,
            queryLayerUrl: parcelsLayerUrl,
            oidField: PARCELS_OID,
          });
          if (features && features.length) {
            const ids = features.map((f) => f.attributes[PARCELS_OID]);
            const buffered = await queryByObjectIds(parcelsLayerUrl, ids, {
              outFields: ["*"], returnGeometry: true, oidField: PARCELS_OID,
            });
            applyResults(buffered, parcelsConfig);
            announce(`Buffer found ${buffered.features.length} parcels within ${distance} feet.`);
          } else {
            announce("Buffer produced no parcels.", { assertive: true });
          }
          break;
        }

        case "adjoiners": {
          const zoomed = await zoomToFeature(view, parcelsLayerUrl, id, highlightLayer, undefined, PARCELS_OID);
          if (!zoomed) return;
          const adjoiners = await findAdjoiners({
            parcelGeometry: zoomed.geometry,
            parcelLayerUrl: parcelsLayerUrl,
            bufferLayer,
            oidField: PARCELS_OID,
          });
          const ids = adjoiners.map((f) => f.attributes[PARCELS_OID]);
          const adj = await queryByObjectIds(parcelsLayerUrl, ids, {
            outFields: ["*"], returnGeometry: true, oidField: PARCELS_OID,
          });
          applyResults(adj, parcelsConfig);
          announce(`Found ${adj.features.length} adjoining parcels.`);
          break;
        }

        case "report":
          openParcelReport({
            objectId: id,
            layerUrl: parcelsLayerUrl,
            reportBaseUrl: CONFIG.reportBaseUrl,
            visibleLayers: [],
            basemap: map.basemap.id,
            extent: view.extent,
          });
          break;

        case "taxinfo":
          openTaxInfo(id);
          break;

        case "permits":
          await openPermits(addressLayerUrl, id, undefined, ADDRESSES_OID);
          break;
      }
    } catch (err) {
      console.error(`Action "${action}" failed:`, err);
      announce(`Action "${action}" failed: ${err.message || err}`, { assertive: true });
    }
  },

  onExport: () => {
    if (!lastFeatureSet || !lastFeatureSet.features.length) return;
    exportFeatureSetToCSV(lastFeatureSet, `durham_${lastLayerConfig?.id || "results"}.csv`);
    announce("CSV export started.");
  },
});

/**
 * Single write path for result sets. Keeps map selection, the results table,
 * and the announcement feed in sync — this is the CAV pipeline from the
 * webrootWCAG starter, now carrying webroot5's richer feature set.
 */
function applyResults(featureSet, layerConfig) {
  lastFeatureSet = featureSet;
  lastLayerConfig = layerConfig;
  table.load(featureSet, {
    layerType: layerConfig?.actionType || "generic",
    oidField:  layerConfig?.oidField   || featureSet.objectIdFieldName,
    priorityFields:      layerConfig?.priorityFields,
    deprioritizedFields: layerConfig?.deprioritizedFields,
  });
  selectFeatures(selectionLayer, featureSet.features || []);
}

// ===========================================================================
//  Header-bar search — FieldPicker + Calcite input + submit button
//
//  FIELD_SEARCH is derived from LayerRegistry.searchFields, plus dev-case
//  and permit entries that aren't in a layer config yet (mirrors webroot5).
// ===========================================================================

const esc = (v) => String(v).replace(/'/g, "''");

const parcelTarget = {
  layerUrl: parcelsLayerUrl,
  layerConfig: parcelsConfig,
};
const addressTarget = {
  layerUrl: addressLayerUrl,
  layerConfig: addressesConfig,
};

const FIELD_SEARCH = {
  REID: {
    ...parcelTarget,
    badge: "#", chipKind: "info",
    label: "REID", placeholder: "Search by REID, e.g. 123456",
    where: (v) => `REID LIKE '${esc(v)}%'`,
  },
  OWNER: {
    ...parcelTarget,
    badge: "O", chipKind: "success",
    label: "Owner", placeholder: "Search by owner name",
    where: (v) => `UPPER(PROPERTY_OWNER) LIKE UPPER('%${esc(v)}%')`,
  },
  ADDRESS: {
    ...parcelTarget,
    badge: "A", chipKind: "brand",
    label: "Address", placeholder: "Search by address, e.g. 200 E Main St",
    where: (v) => `UPPER(LOCATION_ADDR) LIKE UPPER('%${esc(v)}%')`,
  },
  ADDRPOINT: {
    ...addressTarget,
    badge: "P", chipKind: "brand",
    label: "Address Point", placeholder: "Search address points",
    where: (v) => `UPPER(FULL_ADDRESS) LIKE UPPER('%${esc(v)}%')`,
  },
  DEVCASE: {
    layerUrl: ALL_DEV_CASES,
    layerConfig: { actionType: "generic", oidField: "OBJECTID", title: "Dev Cases" },
    badge: "D", chipKind: "warning",
    label: "Dev Case", placeholder: "Dev case number, e.g. D05-12",
    where: (v) => `UPPER(A_NUMBER) LIKE UPPER('${esc(v)}%')`,
  },
  PERMIT: {
    layerUrl: BUILDING_PERMITS,
    layerConfig: { actionType: "generic", oidField: "OBJECTID", title: "Permits" },
    badge: "B", chipKind: "danger",
    label: "Permit", placeholder: "Permit number",
    where: (v) => `UPPER(PermitNum) LIKE UPPER('${esc(v)}%')`,
  },
};

const fieldPicker = initFieldPicker({
  fields: Object.entries(FIELD_SEARCH).map(([value, spec]) => ({
    value,
    label: spec.label,
    badge: spec.badge,
    chipKind: spec.chipKind,
    placeholder: spec.placeholder,
  })),
  onChange: (_value, entry) => {
    announce(`Search field set to ${entry.label}.`);
  },
});

const searchInput     = document.getElementById("search-input");
const searchSubmitBtn = document.getElementById("search-submit-btn");
const tableRegion     = document.getElementById("data-table-region");

async function runSearch() {
  const raw = (searchInput.value ?? "").trim();
  if (!raw) {
    announce("Enter a search term first.", { assertive: true });
    searchInput.setFocus?.();
    return;
  }
  const field = fieldPicker.getField();
  const spec = FIELD_SEARCH[field];
  if (!spec) return;

  searchSubmitBtn.loading = true;
  announce(`Searching for "${raw}"…`);
  try {
    const results = await queryByWhere(spec.layerUrl, spec.where(raw), {
      outFields: ["*"],
      returnGeometry: true,
      outSpatialReference: view.spatialReference,
    });
    applyResults(results, spec.layerConfig);
    announce(
      `Search complete. ${results.features.length} result${results.features.length === 1 ? "" : "s"}.`
    );
    const geoms = results.features.map((f) => f.geometry).filter(Boolean);
    if (geoms.length) await view.goTo(geoms, { animate: !prefersReducedMotion });

    if (!tableRegion.hasAttribute("hidden")) {
      const firstRow = tableRegion.querySelector("tbody tr");
      firstRow?.focus();
    }
  } catch (err) {
    console.error("Search failed:", err);
    announce(`Search failed: ${err?.message || "unknown error"}.`, { assertive: true });
  } finally {
    searchSubmitBtn.loading = false;
  }
}

searchSubmitBtn.addEventListener("click", runSearch);
searchInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") {
    e.preventDefault();
    runSearch();
  }
});

// ===========================================================================
//  Query builder panel
// ===========================================================================

const QUERYABLE_LAYERS = [
  ...LayerRegistry.queryable().map((c) => ({
    id: c.id,
    title: c.title,
    queryUrl: c.queryUrl,
    oidField: c.oidField,
    actionType: c.actionType ?? "generic",
    priorityFields: c.priorityFields,
    deprioritizedFields: c.deprioritizedFields,
  })),
  {
    id: "devtiers",
    title: "Development Tiers",
    queryUrl: DEVELOPMENT_TIERS_URL,
    oidField: "OBJECTID",
    actionType: "generic",
  },
];

const qb = new QueryBuilder({
  container: document.getElementById("query-builder-host"),
  layers: QUERYABLE_LAYERS,
  onSubmit: async (layerCfg, where) => {
    announce(`Running query on ${layerCfg.title}…`);
    try {
      const results = await queryByWhere(layerCfg.queryUrl, where, {
        outFields: ["*"],
        returnGeometry: true,
        outSpatialReference: view.spatialReference,
      });
      applyResults(results, layerCfg);
      qb.setStatus(`${results.features.length} result(s).`);
      announce(`Query complete. ${results.features.length} result${results.features.length === 1 ? "" : "s"}.`);
      const geoms = results.features.map((f) => f.geometry).filter(Boolean);
      if (geoms.length) await view.goTo(geoms, { animate: !prefersReducedMotion });
    } catch (err) {
      console.error("Query builder submit failed:", err);
      qb.setStatus(`Query failed: ${err.message || err}`);
      announce(`Query failed: ${err.message || err}`, { assertive: true });
    }
  },
});

// ===========================================================================
//  Header toggle actions
// ===========================================================================

const layersPanel    = document.getElementById("layers-panel");
const toggleLayersBtn = document.getElementById("toggle-layers-btn");
toggleLayersBtn.addEventListener("click", () => {
  const nowOpen = layersPanel.hasAttribute("collapsed");
  if (nowOpen) {
    layersPanel.removeAttribute("collapsed");
    toggleLayersBtn.setAttribute("aria-expanded", "true");
    toggleLayersBtn.setAttribute("aria-pressed", "true");
    toggleLayersBtn.setAttribute("active", "");
    announce("Layers panel opened.");
  } else {
    layersPanel.setAttribute("collapsed", "");
    toggleLayersBtn.setAttribute("aria-expanded", "false");
    toggleLayersBtn.setAttribute("aria-pressed", "false");
    toggleLayersBtn.removeAttribute("active");
    announce("Layers panel closed.");
  }
});

const queryPanel    = document.getElementById("query-panel");
const toggleQueryBtn = document.getElementById("toggle-query-btn");
toggleQueryBtn.addEventListener("click", () => {
  const nowOpen = queryPanel.hasAttribute("collapsed");
  if (nowOpen) {
    queryPanel.removeAttribute("collapsed");
    toggleQueryBtn.setAttribute("aria-expanded", "true");
    toggleQueryBtn.setAttribute("aria-pressed", "true");
    toggleQueryBtn.setAttribute("active", "");
    announce("Query builder panel opened.");
  } else {
    queryPanel.setAttribute("collapsed", "");
    toggleQueryBtn.setAttribute("aria-expanded", "false");
    toggleQueryBtn.setAttribute("aria-pressed", "false");
    toggleQueryBtn.removeAttribute("active");
    announce("Query builder panel closed.");
  }
});

const toggleTableBtn = document.getElementById("toggle-table-btn");
toggleTableBtn.addEventListener("click", () => {
  const nowOpen = tableRegion.hasAttribute("hidden");
  if (nowOpen) {
    tableRegion.removeAttribute("hidden");
    toggleTableBtn.setAttribute("aria-expanded", "true");
    toggleTableBtn.setAttribute("aria-pressed", "true");
    toggleTableBtn.setAttribute("active", "");
    announce("Data table shown.");
  } else {
    tableRegion.setAttribute("hidden", "");
    toggleTableBtn.setAttribute("aria-expanded", "false");
    toggleTableBtn.setAttribute("aria-pressed", "false");
    toggleTableBtn.removeAttribute("active");
    announce("Data table hidden.");
  }
});

const helpModal    = document.getElementById("help-modal");
const helpBtn      = document.getElementById("help-btn");
const helpCloseBtn = document.getElementById("help-close-btn");
helpBtn.addEventListener("click", () => { helpModal.open = true; });
helpCloseBtn.addEventListener("click", () => { helpModal.open = false; });

// ===========================================================================
//  Menu sheet (top-left hamburger → offcanvas drawer)
// ===========================================================================

const navSheet     = document.getElementById("nav-sheet");
const navMenuBtn   = document.getElementById("nav-menu-btn");
const navSheetPanel = document.getElementById("nav-sheet-panel");

navMenuBtn.addEventListener("click", () => {
  navSheet.open = true;
  navMenuBtn.setAttribute("aria-expanded", "true");
  announce("Menu opened.");
});
navSheet.addEventListener("calciteSheetClose", () => {
  navMenuBtn.setAttribute("aria-expanded", "false");
  navMenuBtn.setFocus?.();
  announce("Menu closed.");
});
navSheetPanel.addEventListener("calcitePanelClose", () => {
  navSheet.open = false;
});

// Preset links: close sheet, announce selection.
// Real preset behavior (toggling layer visibility, zooming, etc.) plugs in
// later — for now these are WCAG-clean placeholders that confirm activation.
navSheet.querySelectorAll(".nav-sheet-item[data-preset]").forEach((a) => {
  a.addEventListener("click", (e) => {
    e.preventDefault();
    const preset = a.dataset.preset;
    const label = a.querySelector("span")?.textContent?.trim() || preset;
    navSheet.open = false;
    announce(`Preset "${label}" selected.`);
  });
});
